"""Seating charts built from a class roster."""

def _sorted_names(students):
    ordered = sorted(
        students,
        key=lambda item: (item.last_name, item.first_name))
    return [item.display_name for item in ordered]

def _chunks(names, size):
    return [names[left:left + size]
            for left in range(0, len(names), size)]

def _row_line(number, names):
    return f"Row {number}: " + " | ".join(names)

def seat_rows(students, seats):
    """Return one text line per row, sorted by last name."""
    if seats < 1 or not students:
        raise ValueError("need students and a seat count")
    names = _sorted_names(students)
    rows = _chunks(names, seats)
    return [_row_line(*pair) for pair in enumerate(rows, 1)]

