import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student

def make(last, first):
    return Student("id", last, first, "A")

class SeatRowsTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make("Halloway", "Juno"),
            make("Zeller", "Omar"),
            make("Dunmere", "Piet")
        ]

    def test_sorted_and_split_into_rows(self):
        self.assertEqual(
            seat_rows(self.students, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Zeller, Omar"
            ])

    def test_bad_seat_count_raises(self):
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seat_rows(self.students, seats)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([], 3)
